preConditionHook:
// SWING STRUCTURE TREND (Brian's notes I4, TRIAGE I4, p. 4), a pane-2 filter.
// With strength-30 swing pivots ("30 bars per side"): the most recent confirmed
// swing high above the one before it AND the most recent swing low above the one
// before it -- higher highs and higher lows -- is an uptrend, LONG. Both lower is
// a downtrend, SHORT. Anything else is a range, true on neither side; negating
// ONE side admits the other trend, so a range placement needs both negated.
//
// Not HigherSwingLow, which reads ONE series per side (long: higher low only;
// short: lower high only): flipping or negating it cannot supply the second
// series, since negation admits equality and turns the missing-pivot guard
// into a pass.
//
// Pivot scan inlined from HigherSwingLow verbatim (Occurrences 1 and 2 of the
// measured SwingLow / SwingHigh): mixed test, lag exactly strength -- 30 bars
// here, so a pivot is known 30 bars after it printed -- offsets
// strength..maxBarsBack-1, deepest bar maxBarsBack - 1 + strength; maxBarsBack
// must hold two pivots of each kind. Existence is a bool set on the SECOND
// pivot, never a price test against -1.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
lo1 = 0.0;
lo2 = 0.0;
haveLo = false;
foundLo = 0;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) {
        ++foundLo;
        if (foundLo == 1) { lo1 = low[pj]; }
        else { lo2 = low[pj]; haveLo = true; break; }
    }
}
hi1 = 0.0;
hi2 = 0.0;
haveHi = false;
foundHi = 0;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) {
        ++foundHi;
        if (foundHi == 1) { hi1 = high[pj]; }
        else { hi2 = high[pj]; haveHi = true; break; }
    }
}
